const raw = $input.first().json;
const b = raw.body ?? raw;
const reasons = [];
const phone = b.smsPhone || null;
const consent = (b.consent && b.consent.smsMarketing === true);
if (!phone) reasons.push('no-smsPhone');
else if (!/^\+[1-9][0-9]{7,14}$/.test(phone)) reasons.push('formato-no-E164');
if (!consent) reasons.push('sin-consentimiento-sms');
const txt = b.smsText || '';
if (!txt) reasons.push('texto-vacio');
if (txt.length > 160) reasons.push('longitud-excede-160');
if (/\$\$\$/.test(txt) || /FREE!!/.test(txt)) reasons.push('contenido-spam');
const st = $getWorkflowStaticData('global');
st.freq = st.freq || {};
const key = phone || 'none';
const now = Date.now();
st.freq[key] = (st.freq[key] || []).filter(t => now - t < 30*24*3600*1000);
if (st.freq[key].length >= 3) reasons.push('frequency-cap-3-30d');
st.warm = st.warm || {};
const sender = b.senderNumber || 'default';
const day = new Date(now).toISOString().slice(0,10);
if (!st.warm[sender]) st.warm[sender] = {firstSeen: day, days: {}};
const w = st.warm[sender];
const ageDays = Math.floor((now - Date.parse(w.firstSeen + 'T00:00:00Z')) / 86400000);
w.days[day] = w.days[day] || 0;
if (ageDays < 7 && w.days[day] >= 200) reasons.push('warmup-cap-200-dia');
const ok = reasons.length === 0;
if (ok) { st.freq[key].push(now); w.days[day]++; }
return [{json:{ok:ok, reasons:reasons, quietHours:'ventana 09:00-21:00 LST se aplica en scheduler'}}];
